import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number }> }} invoice
 * @returns {string} Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // Header: invoice number or DRAFT
  const header = invoice.number ?? 'DRAFT';
  lines.push(header);

  // Customer name
  const customerResult = getCustomer(invoice.customerId);
  if (customerResult.ok) {
    lines.push(customerResult.value.name);
  }

  // Line items
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const qtyDisplay = line.qty;
    const nameDisplay = line.name;
    const priceDisplay = formatEuros(line.unitPrice);
    const totalDisplay = formatEuros(total);

    if (discount > 0) {
      const discountDisplay = formatEuros(discount);
      const discountedDisplay = formatEuros(total - discount);
      lines.push(`${qtyDisplay}x ${nameDisplay} @ ${priceDisplay} = ${totalDisplay} (${line.discountPercent}% off: -${discountDisplay}) = ${discountedDisplay}`);
    } else {
      lines.push(`${qtyDisplay}x ${nameDisplay} @ ${priceDisplay} = ${totalDisplay}`);
    }
  }

  // Totals
  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    const subtotalDisplay = formatEuros(totals.subtotal);
    const discountDisplay = formatEuros(totals.discount);
    lines.push(`Subtotal: ${subtotalDisplay}`);
    lines.push(`Discount: -${discountDisplay}`);
  }
  const totalDisplay = formatEuros(totals.total);
  lines.push(`Total: ${totalDisplay}`);

  return lines.join('\n');
}

