import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice succeeds with valid customer, date, and one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(result.value.lines[0].name, 'Logo package');
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[0].unitPrice, 120000);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice succeeds with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(result.value.lines[1].sku, 'BRAND-BOOK');
  assert.equal(result.value.lines[1].name, 'Brand guidelines document');
  assert.equal(result.value.lines[1].qty, 2);
});

test('createInvoice fails with unknown customer', () => {
  const result = createInvoice({
    customerId: 'UNKNOWN',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice fails with invalid date format', () => {
  const tests = [
    '2025-10-7',
    '2025-1-07',
    '25-10-07',
    '10-07-2025',
    '2025/10/07',
    'invalid',
    '2025-13-01',
    '2025-02-30',
  ];

  for (const dateStr of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    });

    assert.equal(result.ok, false, `Should fail for date: ${dateStr}`);
    assert.equal(result.error, 'DATE_INVALID', `Should fail with DATE_INVALID for date: ${dateStr}`);
  }
});

test('createInvoice fails with empty lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice fails with non-array lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: null,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice fails with invalid quantity', () => {
  const tests = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'non-integer' },
    { qty: '2', desc: 'string' },
    { qty: null, desc: 'null' },
  ];

  for (const { qty, desc } of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'LOGO-PACK', qty }],
    });

    assert.equal(result.ok, false, `Should fail for ${desc}`);
    assert.equal(result.error, 'QTY_INVALID', `Should fail with QTY_INVALID for ${desc}`);
  }
});

test('createInvoice fails with unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'UNKNOWN_SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  };
  const original = JSON.stringify(input);

  createInvoice(input);

  assert.equal(JSON.stringify(input), original);
});

test('lineTotal calculates qty * unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 120000 }), 240000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 50 }), 250);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
});

test('lineTotal returns integer cents', () => {
  const result = lineTotal({ qty: 3, unitPrice: 6000 });
  assert.equal(Number.isInteger(result), true);
  assert.equal(result, 18000);
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 120000 },
      { qty: 2, unitPrice: 245000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 610000);
  assert.equal(totals.total, 610000);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 8500 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.total, 25500);
});

test('invoiceTotals with multiple lines of varying prices', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 120000 },
      { qty: 2, unitPrice: 9500 },
      { qty: 4, unitPrice: 37 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000 + 19000 + 148);
  assert.equal(totals.total, 139148);
});

test('invoiceTotals with invoices created from createInvoice', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 120000 + 245000);
  assert.equal(totals.total, 365000);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 120000 }],
  };
  const original = JSON.stringify(invoice);

  invoiceTotals(invoice);

  assert.equal(JSON.stringify(invoice), original);
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'BRAND-BOOK', qty: 2 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[1].sku, 'BRAND-BOOK');
  assert.equal(addResult.value.lines[1].name, 'Brand guidelines document');
  assert.equal(addResult.value.lines[1].qty, 2);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 3 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(addResult.value.lines[0].qty, 5);
});

test('addLine fails with invalid quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const tests = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'non-integer' },
  ];

  for (const { qty, desc } of tests) {
    const addResult = addLine(result.value, { sku: 'BRAND-BOOK', qty });
    assert.equal(addResult.ok, false, `Should fail for ${desc}`);
    assert.equal(addResult.error, 'QTY_INVALID', `Should fail with QTY_INVALID for ${desc}`);
  }
});

test('addLine fails with unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'UNKNOWN_SKU', qty: 1 });

  assert.equal(addResult.ok, false);
  assert.equal(addResult.error, 'UNKNOWN_SKU');
});

test('addLine fails if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 }],
