  assert.equal(result.ok, true);
  const original = JSON.stringify(result.value);

  addLine(result.value, { sku: 'BRAND-BOOK', qty: 1 });

  assert.equal(JSON.stringify(result.value), original);
});

test('removeLine removes a line from the invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'LOGO-PACK');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'BRAND-BOOK');
});

test('removeLine fails if SKU is not on invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'UNKNOWN_SKU');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'LINE_NOT_FOUND');
});

test('removeLine fails if it would remove the last line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
