test('removeLine fails if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 },
      { sku: 'BRAND-BOOK', name: 'Brand guidelines document', qty: 1, unitPrice: 245000, vatRate: 21 },
    ],
  };

  const removeResult = removeLine(invoice, 'LOGO-PACK');

  assert.equal(removeResult.ok, false);
  assert.equal(removeResult.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const original = JSON.stringify(result.value);

  removeLine(result.value, 'LOGO-PACK');

  assert.equal(JSON.stringify(result.value), original);
});

test('addLine and removeLine work together in a sequence', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(createResult.ok, true);

  const addResult1 = addLine(createResult.value, { sku: 'BRAND-BOOK', qty: 1 });
  assert.equal(addResult1.ok, true);
  assert.equal(addResult1.value.lines.length, 2);

  const addResult2 = addLine(addResult1.value, { sku: 'ICON-SET', qty: 3 });
  assert.equal(addResult2.ok, true);
  assert.equal(addResult2.value.lines.length, 3);

  const removeResult = removeLine(addResult2.value, 'BRAND-BOOK');
  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 2);
  assert.equal(removeResult.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(removeResult.value.lines[1].sku, 'ICON-SET');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2025-0001');
  assert.equal(issueResult.value.status, 'issued');
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2025-10-07');
  assert.equal(issueResult.value.lines.length, 1);
});

test('issueInvoice increments invoice number', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 2 }],
  });

  assert.equal(result.ok, true);
  const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
  const issueResult = issueInvoice(result.value, existingNumbers);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2025-0003');
});

test('issueInvoice restarts counter for new year', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const existingNumbers = ['INV-2025-0050'];
  const issueResult = issueInvoice(result.value, existingNumbers);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2026-0001');
});

test('issueInvoice fails if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'issued',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 }],
  };

  const issueResult = issueInvoice(invoice, []);

  assert.equal(issueResult.ok, false);
  assert.equal(issueResult.error, 'NOT_DRAFT');
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const original = JSON.stringify(result.value);

  issueInvoice(result.value, []);

  assert.equal(JSON.stringify(result.value), original);
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.number, undefined);
});

test('issueInvoice preserves all invoice data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, ['INV-2025-0001']);

  assert.equal(issueResult.ok, true);
  assert.equal(issueResult.value.number, 'INV-2025-0002');
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2025-10-07');
  assert.equal(issueResult.value.lines.length, 2);
  assert.equal(issueResult.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(issueResult.value.lines[0].name, 'Logo package');
  assert.equal(issueResult.value.lines[1].sku, 'BRAND-BOOK');
  assert.equal(issueResult.value.lines[1].name, 'Brand guidelines document');
});

test('createInvoice accepts and stores discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
