test('TIER_DISCOUNTS is exported', () => {
  assert.deepEqual(TIER_DISCOUNTS, {
    gold: 5,
    silver: 2.5,
    standard: 0,
  });
});

test('createInvoice applies gold tier discount', () => {
  // C-008 is Lumen Records with gold tier
  const result = createInvoice({
