    { discount: -1, desc: 'negative' },
    { discount: 101, desc: 'over 100' },
    { discount: 'ten', desc: 'string' },
    { discount: NaN, desc: 'NaN' },
  ];

  for (const { discount, desc } of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: discount }],
    });

    assert.equal(result.ok, false, `Should fail for ${desc}`);
    assert.equal(result.error, 'DISCOUNT_INVALID', `Should fail with DISCOUNT_INVALID for ${desc}`);
  }
});

test('createInvoice accepts zero and 100 percent discounts', () => {
