test('createInvoice accepts zero and 100 percent discounts', () => {
  const result0 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });

  assert.equal(result0.ok, true);

  const result100 = createInvoice({
    customerId: 'C-001',
