});

test('lineDiscount calculates discount amount', () => {
  const line = { qty: 2, unitPrice: 120000, discountPercent: 10 };
  const discount = lineDiscount(line);
  // 2 * 120000 = 240000, 10% = 24000
  assert.equal(discount, 24000);
});

test('lineDiscount returns 0 without discount', () => {
  const line = { qty: 2, unitPrice: 120000 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount handles decimal discounts', () => {
  const line = { qty: 1, unitPrice: 100000, discountPercent: 12.5 };
  const discount = lineDiscount(line);
  // 100000 * 12.5 / 100 = 12500
  assert.equal(discount, 12500);
});

test('invoiceTotals includes discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // LOGO-PACK: 120000 cents
  // 10% discount = 12000 cents
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 12000);
  assert.equal(totals.total, 108000);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
      { sku: 'BRAND-BOOK', qty: 1, discountPercent: 20 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // LOGO-PACK: 120000, 10% discount = 12000
  // BRAND-BOOK: 245000, 20% discount = 49000
  // subtotal: 365000, discount: 61000, total: 304000
  assert.equal(totals.subtotal, 365000);
  assert.equal(totals.discount, 61000);
  assert.equal(totals.total, 304000);
});

test('invoiceTotals clamps total at 0', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100000, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);

  // 100% discount should result in total of 0, not negative
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 100000);
  assert.equal(totals.total, 0);
});

