test('invoiceTotals includes discount', () => {
  // C-001 is gold tier with 5% automatic discount, but explicit 10% override
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
