test('addLine and removeLine work together in a sequence', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(createResult.ok, true);

  const addResult1 = addLine(createResult.value, { sku: 'BRAND-BOOK', qty: 1 });
  assert.equal(addResult1.ok, true);
  assert.equal(addResult1.value.lines.length, 2);

  const addResult2 = addLine(addResult1.value, { sku: 'ICON-SET', qty: 3 });
  assert.equal(addResult2.ok, true);
  assert.equal(addResult2.value.lines.length, 3);

  const removeResult = removeLine(addResult2.value, 'BRAND-BOOK');
