  // Should show VAT line
  assert(text.includes('VAT:'));
});

test('renderInvoiceText VAT with zero-rated item', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // WORKSHOP-DAY has 0% VAT
  // Should not show VAT line or show 0 VAT
  assert(!text.includes('VAT:') || text.includes('VAT: +€0.00'));
});

