  const text = renderInvoiceText(result.value);

  assert(text.includes('12.5% off'));
});

test('renderInvoiceText shows VAT line', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // LOGO-PACK: 120000, VAT 21% = 25200
  assert(text.includes('VAT: +€252.00'));
});

test('renderInvoiceText with discount and VAT', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  // Should have discount and VAT lines
  assert(text.includes('Discount: -€120.00'));
  assert(text.includes('VAT: +€226.80'));
  // Total should be calculated correctly: 120000 - 12000 + 22680 = 130680
  assert(text.includes('Total: €1,306.80'));
});

test('renderInvoiceText with multiple lines different VAT rates', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },     // 21% VAT
      { sku: 'PRINT-A4', qty: 100 },    // 9% VAT
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // Should show correct line items
  assert(text.includes('Logo package'));
  assert(text.includes('Printed flyer A4'));
  // Should show VAT line
  assert(text.includes('VAT:'));
});

test('renderInvoiceText VAT with zero-rated item', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  // WORKSHOP-DAY has 0% VAT
  // Should not show VAT line or show 0 VAT
  assert(!text.includes('VAT:') || text.includes('VAT: +€0.00'));
});

